rows,cols=20,24
g=[[7]*cols for _ in range(rows)]
for r, cs in {4:[15,16,18,19,20,21,22,23],5:[15,23],6:[15,23],7:[23],8:[15],9:[15,23],10:list(range(15,24))}.items():
 for c in cs:g[r][c]=0
# bridge aligned zeros in rows and columns, only if there are zero endpoints across a gap
for r in range(rows):
 cs=[c for c,x in enumerate(g[r]) if x==0]
 for a,b in zip(cs,cs[1:]):
  if b>a+1:
   for c in range(a+1,b):g[r][c]=2
for c in range(cols):
 rs=[r for r in range(rows) if g[r][c]==0]
 for a,b in zip(rs,rs[1:]):
  if b>a+1:
   for r in range(a+1,b):
    if g[r][c]==7:g[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g))
